  const { testObj } = await import('../imports/test')
  console.log('testObj loaded')
  return { json: json.default, testObj }
}

Meteor.startup(() =&gt; {
  imports().then(({ json, testObj }) =&gt; {
    console.log('all loaded: ', json, testObj)
  })
})
</code></pre>

